SET DEFINE OFF
SET FEEDBACK OFF
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT ROLLBACK
SPOOL C:\miguel\c003-carga-cie10-salida.txt

PROMPT === 1) Antes: claves en el catalogo y en el respaldo ===
SELECT COUNT(*) AS CLAVES_HOY FROM SERV_MED_CAT_INDICE_IDC10;
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM SERV_MED_CAT_IDC10_RESP_18NOV;
  IF n < 909 THEN
    RAISE_APPLICATION_ERROR(-20001, 'El respaldo SERV_MED_CAT_IDC10_RESP_18NOV tiene ' || n || ' claves (se esperaban 909). No se carga nada.');
  END IF;
  DBMS_OUTPUT.PUT_LINE('Respaldo OK: ' || n || ' claves');
END;
/

PROMPT === 2) Reemplazo del catalogo (una sola transaccion: si algo falla no queda a medias) ===
DELETE FROM SERV_MED_CAT_INDICE_IDC10;
COMMIT;

SET FEEDBACK ON
PROMPT === 3) Despues: total y claves por letra ===
PROMPT (debe dar 14485)
SELECT COUNT(*) AS CLAVES_DESPUES FROM SERV_MED_CAT_INDICE_IDC10;
SELECT SUBSTR(CLAVE_ID, 1, 1) AS LETRA, COUNT(*) AS CLAVES FROM SERV_MED_CAT_INDICE_IDC10 GROUP BY SUBSTR(CLAVE_ID, 1, 1) ORDER BY 1;
PROMPT === 4) Muestra: rinofaringitis, lumbalgia y cefalea ===
SELECT CLAVE_ID, CLAVE_NOMBRE FROM SERV_MED_CAT_INDICE_IDC10 WHERE CLAVE_ID IN ('J00.X', 'M54.5', 'R51.X') ORDER BY 1;
SPOOL OFF
